files.styles.css:
/* Basic reset */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: Arial, Helvetica, sans-serif;
  background: #f0f2f5;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100vh;
}

.login-wrapper {
  background: #fff;
  padding: 2rem;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,.1);
  width: 320px;
}

h2 {
  text-align: center;
  margin-bottom: 1.5rem;
  color: #1877f2;
}

label {
  font-size: .9rem;
  margin-top: .5rem;
  display: block;
}

input {
  width: 100%;
  padding: .75rem;
  margin-top: .25rem;
  margin-bottom: .75rem;
  border: 1px solid #ccd0d5;
  border-radius: 4px;
  font-size: 1rem;
}

input:focus {
  outline: none;
  border-color: #1877f2;
  box-shadow: 0 0 0 2px rgba(24,119,242,.2);
}

button {
  width: 100%;
  padding: .75rem;
  background: #1877f2;
  color: #fff;
  border: none;
  border-radius: 4px;
  font-size: 1rem;
  cursor: pointer;
  margin-top: .5rem;
}

button:hover {
  background: #165eab;
}

.links {
  display: flex;
  justify-content: space-between;
  margin-top: 1rem;
  font-size: .85rem;
}

.links a {
  color: #1877f2;
  text-decoration: none;
}

.links a:hover {
  text-decoration: underline;
}

